import 'dart:io';import 'package:flutter/material.dart';import 'package:provider/provider.dart';import '../../../core/routing/app_router.dart';import '../../../providers/auth_provider.dart';import '../../../providers/incident_provider.dart';import '../../../shared/widgets/app_button.dart';import '../widgets/incident_form.dart';class CreateIncidentScreen extends StatefulWidget{const CreateIncidentScreen({super.key});@override State<CreateIncidentScreen> createState()=>_CreateIncidentScreenState();}class _CreateIncidentScreenState extends State<CreateIncidentScreen>{final keyForm=GlobalKey<FormState>();final titleC=TextEditingController(),descC=TextEditingController(),locC=TextEditingController();String category='Broken Facilities';File? photo;bool submitting=false;@override void dispose(){titleC.dispose();descC.dispose();locC.dispose();super.dispose();}Future<void> submit()async{if(!keyForm.currentState!.validate())return;final auth=context.read<AuthProvider>();final u=auth.firebaseUser;final p=auth.profile;if(u==null||p==null)return;setState(()=>submitting=true);try{await context.read<IncidentProvider>().createIncident(title:titleC.text,description:descC.text,category:category,location:locC.text,uid:u.uid,reporterName:p.name,photo:photo);if(!mounted)return;ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Report submitted.')));Navigator.pushNamedAndRemoveUntil(context,AppRouter.home,(_)=>false);}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('Could not submit: $e')));}finally{if(mounted)setState(()=>submitting=false);}}@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Report an incident')),body:ListView(padding:const EdgeInsets.all(20),children:[const Text('Describe the issue clearly so campus staff can locate it.'),const SizedBox(height:16),IncidentForm(formKey:keyForm,titleController:titleC,descriptionController:descC,locationController:locC,onCategoryChanged:(v)=>category=v,onPhotoChanged:(v)=>photo=v),const SizedBox(height:18),AppButton(label:'Submit report',loading:submitting,onPressed:submit)]));}
